"""Compare planner MLU with an independently solved reference LP."""
import json, sys, time
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0, '/app/work')
from campaign2 import make, KINDS

def worker(task):
    kind, seeds = task
    import subprocess, check as C
    reqs = [make(kind, s) for s in seeds]
    data = "".join(json.dumps(r) + "\n" for r in reqs).encode()
    p = subprocess.run([sys.executable, '/app/submission/planner.py'], input=data,
                       capture_output=True, timeout=900)
    out = p.stdout.decode().splitlines()
    res = []
    for s, r, line in zip(seeds, reqs, out):
        resp = json.loads(line)
        L = C.build(r)
        try:
            ref_st, ref_val = C.reference_optimum(L)
        except Exception as e:
            res.append((s, kind, "REFFAIL %r" % e, "")); continue
        if resp.get("status") == "optimal":
            if ref_st != "optimal":
                res.append((s, kind, "STATUS CONFLICT planner=optimal ref=%s" % ref_st, ""))
            elif abs(resp["mlu"] - ref_val) > 2e-5:
                res.append((s, kind, "MLU MISMATCH %g vs %g" % (resp["mlu"], ref_val), ""))
            else:
                res.append((s, kind, None, ("optimal", abs(resp["mlu"] - ref_val))))
        elif resp.get("status") == "infeasible":
            if ref_st != "infeasible":
                res.append((s, kind, "STATUS CONFLICT planner=infeasible ref=%s %s" % (ref_st, ref_val), ""))
            else:
                res.append((s, kind, None, ("infeasible", 0.0)))
        else:
            res.append((s, kind, "PLANNER INVALID for valid request", ""))
    return res

def main():
    n = int(sys.argv[1]); seed0 = int(sys.argv[2])
    block = int(sys.argv[3]) if len(sys.argv) > 3 else 15
    tasks = []
    i = 0
    while i < n:
        k = KINDS[(i // block) % len(KINDS)]
        tasks.append((k, [seed0 + i + j for j in range(min(block, n - i))]))
        i += block
    bad = 0; worst = 0.0; cnt = {}
    with ThreadPoolExecutor(max_workers=4) as pool:
        for group in pool.map(worker, tasks):
            for seed, kind, err, info in group:
                if err:
                    bad += 1; print("FAIL", kind, seed, err)
                else:
                    cnt[(kind, info[0])] = cnt.get((kind, info[0]), 0) + 1
                    worst = max(worst, info[1])
    print("cross-checked, bad %d, worst |mlu-ref| = %.3g" % (bad, worst))
    for k in sorted(cnt): print("   ", k, cnt[k])
    return 1 if bad else 0

if __name__ == "__main__":
    sys.exit(main())
